package com.justenoughmods.achievementguide.integration.battlearmor;
import com.github.L_Ender.cataclysm.crafting.WeaponfusionRecipe;import com.github.L_Ender.cataclysm.inventory.WeaponfusionMenu;import com.justenoughmods.achievementguide.advancement.QuestResultSnapshot;import com.justenoughmods.achievementguide.integration.battle.*;import com.justenoughmods.achievementguide.integration.food.NativeFoodSources;import java.util.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.SimpleContainer;import net.minecraft.world.entity.player.Player;import net.minecraft.world.inventory.AbstractContainerMenu;import net.minecraft.world.item.*;
public final class WorldBattleArmorQuestFusion {
 public record Take(ItemStack base,ItemStack addition,ItemStack output,boolean valid){}
 public static final class Click {public final ServerPlayer actor;public final AbstractContainerMenu menu;public final List<ItemStack> before;public final List<Take> paid=new ArrayList<>();public Take taking;public Click(ServerPlayer actor,AbstractContainerMenu menu){this.actor=actor;this.menu=menu;before=WorldBattleArmorQuestProof.held(actor).stream().map(ItemStack::copy).toList();}}
 private static final ThreadLocal<ArrayDeque<Click>> CLICKS=ThreadLocal.withInitial(ArrayDeque::new);
 public static Click begin(AbstractContainerMenu menu,Player player){var actor=WorldBattleArmorQuestProof.real(player);if(actor==null||!(menu instanceof WeaponfusionMenu)||actor.containerMenu!=menu||!menu.stillValid(actor)||CLICKS.get().size()>=16)return null;var click=new Click(actor,menu);CLICKS.get().push(click);return click;}
 private static Click current(AbstractContainerMenu menu,Player actor){for(var click:CLICKS.get())if(click.menu==menu&&click.actor==actor)return click;return null;}
 public static void taking(AbstractContainerMenu menu,WeaponfusionRecipe recipe,Player player,ItemStack taken){var click=current(menu,player);if(click==null)return;click.taking=null;if(recipe==null||!recipe.getId().toString().equals("cataclysm:weapon_infusion/ignitium_elytra_chestplate")||player.level().getRecipeManager().byKey(recipe.getId()).orElse(null)!=recipe)return;var base=menu.getSlot(0).getItem().copy();var addition=menu.getSlot(1).getItem().copy();var inputs=new SimpleContainer(base,addition);if(!BattleQuestProof.item(base).equals("cataclysm:ignitium_chestplate")||!addition.is(Items.ELYTRA)||!BattleQuestSmithing.certified(click.actor,base,"ignitium")||!recipe.matches(inputs,player.level()))return;var expected=recipe.assemble(inputs,player.level().registryAccess());var actual=taken.isEmpty()&&menu instanceof QuestResultSnapshot quick?quick.jem$questQuickResult():taken;boolean valid=expected.getCount()==1&&BattleQuestProof.item(expected).equals("cataclysm:ignitium_elytra_chestplate")&&(actual.isEmpty()||ItemStack.isSameItemSameTags(expected,actual));click.taking=new Take(base,addition,expected.copy(),valid);}
 public static void taken(AbstractContainerMenu menu,Player player){var click=current(menu,player);if(click==null)return;var take=click.taking;click.taking=null;if(take!=null&&take.valid&&debit(take.base,menu.getSlot(0).getItem())&&debit(take.addition,menu.getSlot(1).getItem())&&click.paid.size()<16)click.paid.add(take);}
 private static boolean debit(ItemStack before,ItemStack after){return before.getCount()-after.getCount()==1&&(after.isEmpty()||ItemStack.isSameItemSameTags(before,after));}
 public static void end(Click click){if(click==null)return;var q=CLICKS.get();q.removeFirstOccurrence(click);if(q.isEmpty())CLICKS.remove();if(WorldBattleArmorQuestProof.real(click.actor)==null||click.actor.containerMenu!=click.menu)return;var after=WorldBattleArmorQuestProof.held(click.actor);var allocated=new ArrayList<ItemStack>();for(var take:click.paid){if(WorldBattleArmorQuestProof.count(after,take.output)-WorldBattleArmorQuestProof.count(click.before,take.output)-WorldBattleArmorQuestProof.count(allocated,take.output)<1)continue;for(var target:after)if(ItemStack.isSameItemSameTags(target,take.output)&&NativeFoodSources.claims(target).isEmpty()){var sources=NativeFoodSources.get(click.actor.serverLevel());var batch=sources.certify(click.actor.serverLevel(),click.actor.getUUID(),"battle_armor_elytra",target,1);if(batch!=null){WorldBattleEquipmentOrigins.confirmed(click.actor,batch,"battle_armor_elytra",target);for(var old:NativeFoodSources.claims(take.base))sources.activate(old.batch(),false);allocated.add(take.output);break;}}}}
 public static void clear(){CLICKS.remove();}
}
